"""Curated registry rows for the objects of research/alatau_objects.md section 3 (Nos 1-170).

Data only. Words in `place` and in source claims are copied from the research file.
Geometry specs are resolved by build_registry.py:
  ("twin", x, z)          position the twin uses now (Unity X/Z); always with the model chip
  ("ll", lat, lon)        WGS84 from a cited source
  ("ov", theme, id)       Overture feature geometry; ("ovpt", theme, id) its representative point
  ("set", key)            settlement point (build_registry.SETTLEMENTS)
  ("km", road, km, side, offset_m)   point at a km marker of A-3 (OSM milestone fit), offset to a side
  ("ch", road, chainage_km, side, offset_m)  same by chainage from the south end of the A-3 path
  ("mid", spec, spec)     midpoint of two specs; ("seg_a3", spec) segment from spec to nearest A-3 point
  ("ref", row_id)         same geometry as another row;  None  no geometry
"""


def R(**kw):
    return kw


def C(topic, claims, wins, why):
    return {"topic": topic, "claims": [{"source": s, "says": t} for s, t in claims], "wins": wins, "why": why}


